# 1. Add data.js script before </head>
html = html.replace('</head>', '  <script src="data.js"></script>\n</head>')

# 2. Add fetchFunds function before fetchFundMaxDrawdown
fetchFundsCode = '''\n// ==================== 基金排行数据获取 ====================\nasync function fetchFundRankingRaw(ft, pn) {\n  return new Promise((resolve) => {\n    const script = document.createElement('script');\n    const t = Date.now();\n    script.src = 'https://fundapi.eastmoney.com/fundtradenew.aspx?ft='+ft+'&sc=1y&st=desc&pi=1&pn='+pn+'&cp=&ct=&cd=&ms=&fr=&plevel=&fst=&ftype=&fr1=&fl=0&isab=&_=' + t;\n    script.onerror = () => resolve([]);\n    let done = false;\n    const check = () => {\n      if (done) return;\n      if (window.rankData && window.rankData.data1) {\n        done = true;\n        if (script.parentNode) script.parentNode.removeChild(script);\n        const list = window.rankData.data1.map(s => {\n          const p = s.split('|');\n          return {\n            code: p[0] || '',\n            name: p[1] || '',\n            type: (p[2] || '').replace('型',''),\n            nav: parseFloat(p[4]) || 0,\n            ret1w: parseFloat(p[6]) || 0,\n            ret1m: parseFloat(p[7]) || 0,\n            ret3m: parseFloat(p[8]) || 0,\n            ret6m: parseFloat(p[9]) || 0,\n            ret1y: parseFloat(p[10]) || 0\n          };\n        }).filter(f => f.code && f.name);\n        window.rankData = null;\n        resolve(list);\n      }\n    };\n    script.onload = () => { setTimeout(check, 50); setTimeout(() => { if(!done){done=true;resolve([]);} }, 3000); };\n    document.head.appendChild(script);\n    setTimeout(() => { if(!done){done=true;if(script.parentNode)script.parentNode.removeChild(script);resolve([]);} }, 5000);\n  });\n}\n\nasync function fetchFunds() {\n  // 先尝试从 data.js 读取\n  if (typeof window.fundData !== 'undefined' && window.fundData.funds && window.fundData.funds.length > 0) {\n    const valid = window.fundData.funds.filter(f => f.name && f.name !== '--');\n    if (valid.length > 0) {\n      Store.funds = valid;\n      return;\n    }\n  }\n  // 否则从东方财富排行 API 获取\n  try {\n    const all = [];\n    const types = [\n      {ft:'all', pn:50, mapType:null},\n      {ft:'hh', pn:15, mapType:'混合型'},\n      {ft:'gp', pn:15, mapType:'股票型'},\n      {ft:'zq', pn:10, mapType:'债券型'},\n      {ft:'qdii', pn:10, mapType:'QDII'},\n      {ft:'zs', pn:10, mapType:'指数型'}\n    ];\n    for (const t of types) {\n      try {\n        const list = await fetchFundRankingRaw(t.ft, t.pn);\n        for (const f of list) {\n          if (t.mapType) f.type = t.mapType;\n          if (!all.find(x => x.code === f.code)) all.push(f);\n        }\n      } catch(e){}\n    }\n    Store.funds = all;\n  } catch(e) {\n    Store.funds = [];\n  }\n}\n\n'''
html = html.replace('async function fetchFundMaxDrawdown() {', fetchFundsCode + 'async function fetchFundMaxDrawdown() {')

# 3. Make fund rows clickable
oldRow = '''let fundTableHtml = filtered.map((f,i) => `\n    <tr><td class="rank ${i<3?'top3':''}">${i+1}</td>\n      <td><div style="font-weight:500;font-size:11px;">${f.name}</div><div style="font-size:9px;color:#9ca3af;">${f.code} · ${f.type}</div></td>'''
newRow = '''let fundTableHtml = filtered.map((f,i) => `\n    <tr onclick="showFundDetail('${f.code}')" style="cursor:pointer;"><td class="rank ${i<3?'top3':''}">${i+1}</td>\n      <td><div style="font-weight:500;font-size:11px;">${f.name}</div><div style="font-size:9px;color:#9ca3af;">${f.code} · ${f.type}</div></td>'''
html = html.replace(oldRow, newRow)

# 4. Add fetchFunds to loadData initial fetch
oldLoad = '''  // 并发获取基础数据\n  await Promise.all([\n    fetchIndices(),\n    fetchNorthBound(),\n    fetchSectors(),'''
newLoad = '''  // 并发获取基础数据\n  await Promise.all([\n    fetchIndices(),\n    fetchNorthBound(),\n    fetchSectors(),\n    fetchFunds(),'''
